{"code":"import json
import sys
import oracle


def main():
    with open(sys.argv[1], "r", encoding="utf-8") as f:
        public = json.load(f)

    ciphertext = bytes.fromhex(public["ciphertext_hex"])
    if len(ciphertext) != 32 or public["protected_length"] != 15:
        raise ValueError("Expected two ciphertext blocks and a 15-byte protected plaintext")

    previous = ciphertext[:16]
    intermediate = bytearray(16)
    candidate = bytearray(previous)

    # The known plaintext length guarantees a final padding byte of 0x01.
    intermediate[15] = previous[15] ^ 1

    # At most 15 * 256 = 3840 oracle queries are required.
    # The forced final byte fixes the padding length, avoiding ambiguity.
    for padding in range(2, 17):
        position = 16 - padding
        for j in range(position + 1, 16):
            candidate[j] = intermediate[j] ^ padding

        for value in range(256):
            candidate[position] = value
            if oracle.query(candidate.hex()):
                intermediate[position] = value ^ padding
                break
        else:
            raise RuntimeError("No valid padding candidate found")

    plaintext = bytes(intermediate[i] ^ previous[i] for i in range(15))
    print(json.dumps({"plaintext_hex": plaintext.hex()}, separators=(",", ":")))


if __name__ == "__main__":
    main()
"}
